// src/components/BudgetLimits.js
import React, { useState, useEffect } from "react";
import axios from "axios";
import "./BudgetLimits.css";

function BudgetLimits({ formData }) {
  const [budgetLimits, setBudgetLimits] = useState({});
  const [categoriesToShow, setCategoriesToShow] = useState([]);

  useEffect(() => {
    if (!formData.spendingPriority) return;

    // Filter categories with priority >= 3
    const selected = Object.keys(formData.spendingPriority).filter(
      cat => formData.spendingPriority[cat] >= 3
    );

    setCategoriesToShow(selected);

    // Initialize budgetLimits with 0
    const initialLimits = {};
    selected.forEach(cat => (initialLimits[cat] = ""));
    setBudgetLimits(initialLimits);
  }, [formData]);

  const handleChange = (cat, val) => {
    setBudgetLimits(prev => ({ ...prev, [cat]: val }));
  };

  const handleSave = async () => {
    if (!categoriesToShow.length) {
      alert("No categories selected with priority ≥ 3");
      return;
    }

    try {
      const payload = {
        incomeCategory: formData.category,
        questionnaire: formData.questionnaire,
        spendingPriorities: formData.spendingPriority,
        budgetLimits
      };

      await axios.post("http://localhost:5000/save-budget", payload);
      alert("Data saved successfully!");
    } catch (err) {
      console.error(err);
      alert("Failed to save data");
    }
  };

  if (!categoriesToShow.length) {
    return <p style={{ textAlign: "center", color: "red" }}>No categories selected with priority ≥ 3</p>;
  }

  return (
    <div className="budget-container">
      <h2 className="budget-title">Set Monthly Budget Limits</h2>
      <div className="budget-grid">
        {categoriesToShow.map(cat => (
          <div key={cat} className="budget-card">
            <h3 className="budget-name">{cat}</h3>
            <input
              type="number"
              placeholder="Enter monthly limit"
              value={budgetLimits[cat]}
              onChange={e => handleChange(cat, e.target.value)}
              className="budget-input"
            />
          </div>
        ))}
      </div>
      <button className="next-button" onClick={handleSave}>Save</button>
    </div>
  );
}

export default BudgetLimits;
